mapper.select:
select m.id as memberId, m.nickname as nickname, m.avatar as avatar,
       d.score as score
from (
    select member_id, sum(change_points) as score
    from ums_member_points_detail
    where change_type = 1 and del_flag = 0 and create_time >= #{weekStart}
    group by member_id
) d
join ums_member m on m.id = d.member_id and m.del_flag = 0
order by d.score desc, m.create_time asc, m.id asc
limit #{limit}


select
    (select count(*) from (
        select member_id, sum(change_points) as s
        from ums_member_points_detail
        where change_type = 1 and del_flag = 0 and create_time >= #{weekStart}
        group by member_id
    ) t join ums_member ranked on ranked.id = t.member_id and ranked.del_flag = 0
      where t.s > base.s
         or (t.s = base.s
             and (ranked.create_time < base.created
                  or (ranked.create_time = base.created and ranked.id < base.memberId)))) + 1 as userRank,
    (select count(*) from (
        select member_id
        from ums_member_points_detail
        where change_type = 1 and del_flag = 0 and create_time >= #{weekStart}
        group by member_id
    ) c join ums_member counted on counted.id = c.member_id and counted.del_flag = 0) as totalUsers,
    base.s as score
from (
    select d.member_id as memberId, d.s, m.create_time as created
      from (
            select member_id, sum(change_points) as s
              from ums_member_points_detail
             where change_type = 1 and del_flag = 0 and create_time >= #{weekStart}
             group by member_id
      ) d
      join ums_member m on m.id = d.member_id and m.del_flag = 0
     where d.member_id = #{memberId}
) base
